from syntax import parse,PolicyError
from ebpf.create_dfa import create,DENY
import itertools,random,time
R=[{'name':'A','label':20},{'name':'B','label':3},{'name':'C','label':7}]
def ev(n,s):
 op=n[0]
 if op=='match': return tuple(s)==n[1]
 if op=='startswith': return tuple(s[:len(n[1])])==n[1]
 if op=='endswith': return tuple(s[-len(n[1]):])==n[1] if n[1] else True
 if op=='contains':
  p=n[1]; return not p or any(tuple(s[i:i+len(p)])==p for i in range(len(s)-len(p)+1))
 if op=='not': return not ev(n[1],s)
 if op=='and': return ev(n[1],s) and ev(n[2],s)
 if op=='or': return ev(n[1],s) or ev(n[2],s)
def direct(p,s):return any(ev(x,s) for x,a in p.rules if a=='allow') and not any(ev(x,s) for x,a in p.rules if a=='drop')
rng=random.Random(10);t=time.monotonic()
for z in range(1000):
 def path():return ','.join(rng.choice('ABC') for _ in range(rng.randrange(4)))
 def pred(d=0):
  if d>2 or rng.randrange(3): return rng.choice(['match','startswith','endswith','contains'])+'('+path()+')'
  x=pred(d+1)
  if rng.randrange(3)==0:return 'not('+x+')'
  return '('+x+rng.choice([' and ',' or '])+pred(d+1)+')'
 text=''.join(pred()+' '+rng.choice(['allow','drop'])+';' for x in range(rng.randrange(1,5)))
 try:p=parse(text)
 except PolicyError:continue
 im=create(p,R)
